@namespace sv_33e58074646d41318ecb5f6e8d513c13.Components.Pages.Catalog

<div class="product-card" @onclick="HandleCardClick">
    <div class="product-image" role="img" aria-label="@Product.Name">
        @Product.Name
    </div>
    <div class="product-info">
        <h3 class="product-name">@Product.Name</h3>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <div class="product-rating" aria-label="@($"Rating: {Product.Rating:F1} out of 5")">
            @GetStarRating(Product.Rating)
        </div>
        @if (!Product.InStock)
        {
            <span class="badge-out-of-stock">Out of Stock</span>
        }
        <button class="btn-add-to-cart"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick()
    {
        await OnSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        if (Product.InStock)
        {
            await OnAddToCart.InvokeAsync(Product);
        }
    }

    private static string GetStarRating(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

@namespace sv_33e58074646d41318ecb5f6e8d513c13.Components.Pages.Catalog

<aside class="filter-panel">
    <h2>Filters</h2>

    <section class="filter-section">
        <h3>Categories</h3>
        @if (Categories is not null)
        {
            @foreach (var category in Categories)
            {
                <label class="filter-checkbox">
                    <input type="checkbox"
                           checked="@IsSelected(category)"
                           @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                    @category
                </label>
            }
        }
    </section>

    <section class="filter-section">
        <h3>Price Range</h3>
        <div class="price-inputs">
            <label>
                Min
                <input type="number" min="0" step="0.01"
                       value="@_minPrice"
                       @onchange="@(e => _minPrice = ParseDecimal(e.Value))" />
            </label>
            <label>
                Max
                <input type="number" min="0" step="0.01"
                       value="@_maxPrice"
                       @onchange="@(e => _maxPrice = ParseDecimal(e.Value))" />
            </label>
        </div>
    </section>

    <section class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox" @bind="_inStockOnly" />
            In Stock Only
        </label>
    </section>

    <div class="filter-actions">
        <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
    </div>
</aside>

@code {
    [Parameter]
    public List<string>? Categories { get; set; }

    [Parameter]
    public EventCallback<ProductFilter> OnApplyFilters { get; set; }

    [Parameter]
    public EventCallback OnClearFilters { get; set; }

    private List<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private bool IsSelected(string category) => _selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked && !_selectedCategories.Contains(category))
        {
            _selectedCategories.Add(category);
        }
        else if (!isChecked)
        {
            _selectedCategories.Remove(category);
        }
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: _selectedCategories.Count > 0 ? new List<string>(_selectedCategories) : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );
        await OnApplyFilters.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        await OnClearFilters.InvokeAsync();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

@namespace sv_33e58074646d41318ecb5f6e8d513c13.Components.Pages.Catalog

<div class="product-grid-container">
    @* Toolbar *@
    <div class="toolbar">
        <div class="sort-control">
            <label for="sort-select">Sort by:</label>
            <select id="sort-select" value="@SortBy" @onchange="HandleSortChanged">
                <option value="price_asc">Price: Low to High</option>
                <option value="price_desc">Price: High to Low</option>
                <option value="name_asc">Name: A-Z</option>
                <option value="rating_desc">Rating: Highest</option>
            </select>
        </div>
        @if (Result is not null && Result.TotalCount > 0)
        {
            var start = (Result.Page - 1) * Result.PageSize + 1;
            var end = Math.Min(Result.Page * Result.PageSize, Result.TotalCount);
            <span class="showing-label">Showing @start–@end of @Result.TotalCount products</span>
        }
    </div>

    @* Content states *@
    @if (IsLoading)
    {
        <div class="state-message loading">Loading products...</div>
    }
    else if (ErrorMessage is not null)
    {
        <div class="state-message error">
            <p>Error loading products: @ErrorMessage</p>
        </div>
    }
    else if (Result is null || Result.Items.Count == 0)
    {
        <div class="state-message empty">No products found matching your criteria.</div>
    }
    else
    {
        @* Product cards grid *@
        <div class="product-grid">
            @foreach (var product in Result.Items)
            {
                <ProductCard Product="@product"
                             OnSelected="OnProductSelected"
                             OnAddToCart="OnAddToCart" />
            }
        </div>

        @* Pagination *@
        @if (TotalPages > 1)
        {
            <nav class="pagination" aria-label="Product pages">
                <button class="btn-page"
                        disabled="@(Result.Page <= 1)"
                        @onclick="@(() => ChangePage(Result.Page - 1))">
                    Previous
                </button>

                @for (int i = 1; i <= TotalPages; i++)
                {
                    var pageNum = i;
                    <button class="btn-page @(pageNum == Result.Page ? "active" : "")"
                            @onclick="@(() => ChangePage(pageNum))">
                        @pageNum
                    </button>
                }

                <button class="btn-page"
                        disabled="@(Result.Page >= TotalPages)"
                        @onclick="@(() => ChangePage(Result.Page + 1))">
                    Next
                </button>
            </nav>
        }
    }
</div>

@code {
    [Parameter]
    public PagedResult<Product>? Result { get; set; }

    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public bool IsLoading { get; set; }

    [Parameter]
    public string? ErrorMessage { get; set; }

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private int TotalPages => Result is null || Result.PageSize == 0
        ? 0
        : (int)Math.Ceiling((double)Result.TotalCount / Result.PageSize);

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }

    private async Task ChangePage(int page)
    {
        await OnPageChanged.InvokeAsync(page);
    }
}

@page "/catalog"
@namespace sv_33e58074646d41318ecb5f6e8d513c13.Components.Pages.Catalog
@using sv_33e58074646d41318ecb5f6e8d513c13
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <ProductFilterPanel Categories="@_categories"
                        OnApplyFilters="HandleApplyFilters"
                        OnClearFilters="HandleClearFilters" />

    <ProductGrid Result="@_result"
                 SortBy="@_sortBy"
                 IsLoading="@_isLoading"
                 ErrorMessage="@_errorMessage"
                 OnSortChanged="HandleSortChanged"
                 OnPageChanged="HandlePageChanged"
                 OnProductSelected="HandleProductSelected"
                 OnAddToCart="HandleAddToCart" />
</div>

@code {
    private List<string>? _categories;
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _page = 1;
    private const int PageSize = 12;
    private bool _isLoading;
    private string? _errorMessage;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadCategoriesAsync();
        await SearchAsync();
    }

    private async Task LoadCategoriesAsync()
    {
        try
        {
            _categories = await ProductService.GetCategoriesAsync();
        }
        catch
        {
            // Categories failing shouldn't block the page
            _categories = new List<string>();
        }
    }

    private async Task SearchAsync()
    {
        _isLoading = true;
        _errorMessage = null;
        StateHasChanged();

        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _page, PageSize);
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
            _result = null;
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        _filter = filter;
        _page = 1;
        await SearchAsync();
    }

    private async Task HandleClearFilters()
    {
        _filter = new ProductFilter(null, null, null, false);
        _page = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _page = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _page = page;
        await SearchAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private async Task HandleAddToCart(Product product)
    {
        await OnAddToCart.InvokeAsync(product);
    }
}

.catalog-layout {
