    align-items: center;
    justify-content: center;
    color: #888;
    font-size: 0.9rem;
    text-align: center;
    padding: 1rem;
}

::deep .product-info {
    padding: 1rem;
}

::deep .product-name {
    margin: 0 0 0.4rem;
    font-size: 1rem;
}

::deep .product-price {
    font-weight: 600;
    color: #2563eb;
    margin: 0 0 0.4rem;
}

::deep .product-rating {
    color: #f59e0b;
    margin-bottom: 0.5rem;
}

::deep .badge-out-of-stock {
    display: inline-block;
    background: #fee2e2;
    color: #dc2626;
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    margin-bottom: 0.5rem;
}

::deep .btn-add-to-cart {
    width: 100%;
    padding: 0.5rem;
    background: #16a34a;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 500;
}

::deep .btn-add-to-cart:hover:not(:disabled) {
    background: #15803d;
}

::deep .btn-add-to-cart:disabled {
    background: #d1d5db;
    cursor: not-allowed;
}

::deep .pagination {
    display: flex;
    justify-content: center;
    gap: 0.4rem;
    margin-top: 1.5rem;
    padding: 1rem 0;
}

::deep .btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #ccc;
    background: white;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-page:hover:not(:disabled) {
    background: #f0f0f0;
}

::deep .btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

::deep .btn-page.active {
    background: #2563eb;
    color: white;
    border-color: #2563eb;
}

::deep .state-message {
    text-align: center;
    padding: 3rem 1rem;
    color: #666;
}

::deep .state-message.error {
    color: #dc2626;
}

::deep .state-message.loading {
    color: #555;
}

